export function copyIgnored(ctx: WorktreeContext, options: CopyOptions = {}): CommandResult {
  try {
    return copyIgnoredUnchecked(ctx, options);
  } catch (err) {
    if (err instanceof CopyLimitError) return { success: false, output: err.message };
    throw err;
