    fs.symlinkSync(op.target, at);
    return;
  }
  fs.copyFileSync(path.join(sourceRoot, op.rel), at, fs.constants.COPYFILE_FICLONE | fs.constants.COPYFILE_EXCL);
  fs.utimesSync(at, op.atimeMs / 1000, op.mtimeMs / 1000);
}

